 function doorOf(pid){var c=SC.lang,L=window.ssPerson?ssPerson.all():[],used={};for(var i=0;i<L.length;i++){var p=L[i];used[p.c]=used[p.c]||0;var q=(c.slots[p.c]||[])[used[p.c]++];if(p.id===pid)return q?q.door:null}return null}
